const Home = () => {
  return (
    <div>
      <h1>UTAS Link</h1>
      <p>Connecting students with companies for flexible opportunities.</p>

      <div>
        <h3>Search Jobs</h3>
        <input type="text" placeholder="Search by skill or company" />
        <button>Search</button>
      </div>

      <div>
        <h3>Categories</h3>
        <ul>
          <li>Part-time</li>
          <li>Hourly</li>
          <li>Training</li>
        </ul>
      </div>
    </div>
  );
};

export default Home;
